   286  /*************************************************************************
   287  // ph method util
   288  **************************************************************************/
   289
   290  bool ph_is_forced_method(int method) noexcept // predicate
   291  {
   292      return (method >> 24) == -0x80;
   293  }
   294
   295  int ph_force_method(int method) noexcept // mark as forced
   296  {
   297      return method | (0x80u << 24);
   298  }
   299
   300  int ph_forced_method(int method) noexcept // extract the forced method
   301  {
   302      if (ph_is_forced_method(method))
   303          method &= ~(0x80u << 24);
   304      assert_noexcept(method > 0);
   305      return method;
   306  }
