   308  bool ph_skipVerify(const PackHeader &ph) noexcept {
   309      if (M_IS_DEFLATE(ph.method))
   310          return false;
   311      if (M_IS_LZMA(ph.method))
   312          return false;
   313      if (ph.level > 1)
   314          return false;
   315      return true;
   316  }
